brokenCodeTemplate:
#include <iostream>

/* 满 10 分盖一个章 */
int stamp(int score) {
    return score / 10;
}

/* 这段稿子在另一间屋子里也贴了一遍 */
int stamp(int score) {
    return score / 10;
}

int main() {
    int n = 0;
    std::cin >> n;
    int total = 0;
    for (int i = 0; i < n; i++) {
        int score = 0;
        std::cin >> score;
        total += stamp(score);
    }
    std::cout << "一共盖了 " << total << " 个章" << std::endl;
    return 0;
}

